import{_ as l,C as n,c as o,o as i,j as e,G as s,ak as d,a as c}from"./chunks/framework.D7ejh1zC.js";const b="/assets/llm%E5%90%AB%E4%B9%89.B50ssQ-N.png",m="/assets/token%E6%8B%86%E5%88%86.DBJpyu78.svg",v=JSON.parse('{"title":"什么是 LLM","description":"","frontmatter":{},"headers":[],"relativePath":"ai/第二章 AI Agent 工程基础/LLM是什么.md","filePath":"practice/ai/AI Agent+智能大屏设计器/第二章 AI Agent 工程基础/LLM是什么.md","lastUpdated":1787062422000}'),h={name:"ai/第二章 AI Agent 工程基础/LLM是什么.md"};function u(_,a,k,g,L,T){const t=n("mdInfo"),p=n("NolebaseGitContributors"),r=n("NolebaseGitChangelog");return i(),o("div",null,[a[0]||(a[0]=e("h1",{id:"什么是-llm",tabindex:"-1"},[c("什么是 LLM "),e("a",{class:"header-anchor",href:"#什么是-llm","aria-label":'Permalink to "什么是 LLM"'},"​")],-1)),s(t),a[1]||(a[1]=d('<h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>LLM 是一种通过海量数据训练出来的大语言模型，能理解上下文，并通过预测下一个 Token 来生成自然语言内容。</p><p><img src="'+b+`" alt="LLM" loading="lazy"></p><h2 id="transformer-架构是什么" tabindex="-1">Transformer 架构是什么 <a class="header-anchor" href="#transformer-架构是什么" aria-label="Permalink to &quot;Transformer 架构是什么&quot;">​</a></h2><p>Google 最初提出 Transformer，是为了改进机器翻译等序列建模任务；后来大家发现它不仅适合翻译，还特别适合语言理解、文本生成，最终发展成 LLM 这种大模型的核心架构，现在主流 LLM 大多使用 Transformer 架构。</p><p>Transformer 其实就是在不断的预测下一个最可能出现的 Token。 比如这句话：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中国的首都是()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[&#39;上海&#39;, &#39;北京&#39;, &#39;杭州&#39;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>中国的首都是(北京)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>再比如这句：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，我喜欢()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[&#39;你&#39;, &#39;狗&#39;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你 -&gt; 60%</span></span>
<span class="line"><span>狗 -&gt; 40%</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你好，我喜欢你</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>可能因为你比狗强，大模型选择了你。</p><p>其实就是一直找概率最高的那个 token，往后拼接。</p><p>模型不会直接把它当成一整句话处理，而是会先切成 Token。</p><h2 id="token-是什么" tabindex="-1">Token 是什么 <a class="header-anchor" href="#token-是什么" aria-label="Permalink to &quot;Token 是什么&quot;">​</a></h2><p>Token 是模型读取和生成文本的最小片段单位。它可能是一个字、一个词、半个词、标点、空格等。</p><p>我们可以先把《你好，我喜欢你》粗略看成 5 个 Token：</p><table tabindex="0"><thead><tr><th>顺序</th><th>Token</th></tr></thead><tbody><tr><td>1</td><td>你好</td></tr><tr><td>2</td><td>，</td></tr><tr><td>3</td><td>我</td></tr><tr><td>4</td><td>喜欢</td></tr><tr><td>5</td><td>你</td></tr></tbody></table><p><img src="`+m+'" alt="token拆分" loading="lazy"></p><p>LLM 生成这句话时，也不是一次性把整句话写出来，而是一个 Token 一个 Token 地往后生成。还是以上面例子为例，后续可能还会有其他的 Token，如《你好，我喜欢你的狗》。</p><p>不同模型通常会使用不同的 tokenizer，也就是不同的分词/切词规则。所以同一段文字，在不同模型里可能会被切成不同数量的 token。</p>',19)),s(p),s(r)])}const x=l(h,[["render",u]]);export{v as __pageData,x as default};
